INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist SOAP ausschließlich auf XML angewiesen?', 2, '[{"text": "Ja", "correct": true, "because": "XML ist Standardformat"}, {"text": "Nein", "correct": false, "because": "Kein alternatives Format"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit SOAP?', 3, '[{"text": "Strukturierter Datenaustausch", "correct": true, "because": "Definiert Protokoll"}, {"text": "Datenbankabfragen", "correct": false, "because": "Kein direkter Bezug"}, {"text": "UI-Gestaltung", "correct": false, "because": "Anderer Bereich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten gehören zu SOAP?', 5, '[{"text": "XML", "correct": true, "because": "Format für Nachrichten"}, {"text": "WSDL", "correct": true, "because": "Beschreibt Schnittstelle"}, {"text": "CSS", "correct": false, "because": "Für Styling"}, {"text": "JSON", "correct": false, "because": "REST-typisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) WSDL ist optional. b) SOAP ist protokollunabhängig.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "a) ist falsch, WSDL meist nötig"}, {"text": "Beides stimmt", "correct": false, "because": "WSDL zentral"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einer SOAP-Anfrage?', 4, '[{"text": "XML-Struktur", "correct": false, "because": "Kern der Nachricht"}, {"text": "WSDL-Definition", "correct": false, "because": "Beschreibt Dienst"}, {"text": "Farbschema", "correct": true, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob SOAP auch JSON nutzt?', 2, '[{"text": "Nein", "correct": true, "because": "XML ist vorgeschrieben"}, {"text": "Ja", "correct": false, "because": "Nicht standardkonform"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt WSDL in SOAP?', 3, '[{"text": "Schnittstellenbeschreibung", "correct": true, "because": "Definiert Operationen"}, {"text": "Datenkompression", "correct": false, "because": "Kein Zweck"}, {"text": "UI-Validierung", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet SOAP?', 5, '[{"text": "Sicherheit", "correct": true, "because": "Unterstützt WS-Security"}, {"text": "Struktur", "correct": true, "because": "Strenge Spezifikation"}, {"text": "Dynamische Anpassung", "correct": false, "because": "Fest definiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) SOAP ist schwergewichtig. b) Es ist schneller als REST. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "REST oft schneller"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für SOAP?', 4, '[{"text": "XML-Nachricht", "correct": false, "because": "Kernbestandteil"}, {"text": "WSDL-Datei", "correct": false, "because": "Definiert Dienst"}, {"text": "Grafikdesign", "correct": true, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist SOAP nur für HTTP?', 2, '[{"text": "Nein", "correct": true, "because": "Auch SMTP möglich"}, {"text": "Ja", "correct": false, "because": "Protokollflexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften hat eine SOAP-Nachricht?', 4, '[{"text": "Envelope", "correct": true, "because": "Umschließt Daten"}, {"text": "Body", "correct": true, "because": "Enthält Payload"}, {"text": "Farbanpassung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass SOAP veraltet ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Noch in Unternehmen genutzt"}, {"text": "Ja", "correct": false, "because": "Kontextabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei SOAP?', 3, '[{"text": "Korrekte XML-Struktur", "correct": true, "because": "Sichert Funktion"}, {"text": "Schnelle Umsetzung", "correct": false, "because": "Genauigkeit zählt"}, {"text": "UI-Optimierung", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) SOAP unterstützt Sicherheit. b) Es ist flexibler als REST.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "REST flexibler"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat SOAP?', 5, '[{"text": "Komplexität", "correct": true, "because": "Aufwendige Struktur"}, {"text": "Overhead", "correct": true, "because": "XML erhöht Datenmenge"}, {"text": "Schnellere Antwort", "correct": false, "because": "Eher langsamer"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei SOAP unwichtig?', 3, '[{"text": "XML-Validierung", "correct": false, "because": "Sichert Korrektheit"}, {"text": "WSDL-Konsistenz", "correct": false, "because": "Definiert Schnittstelle"}, {"text": "Serverdesign", "correct": true, "because": "Kein direkter Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann SOAP ohne WSDL laufen?', 3, '[{"text": "Ja", "correct": true, "because": "Technisch möglich"}, {"text": "Nein", "correct": false, "because": "WSDL oft erwartet"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob SOAP leichtgewichtig ist?', 2, '[{"text": "Nein", "correct": true, "because": "Schwerer als REST"}, {"text": "Ja", "correct": false, "because": "Hoher Overhead"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element definiert die SOAP-Schnittstelle?', 4, '[{"text": "WSDL", "correct": true, "because": "Beschreibt Dienst"}, {"text": "JSON", "correct": false, "because": "REST-spezifisch"}, {"text": "CSS", "correct": false, "because": "Styling"}]');
